"""In-memory ``messageId`` cache, in-flight registry, and cached-task replay.

Each in-flight registration is an ``InFlightLease``: only the request that owns
the current lease can release the key or record its outcome, so a late save
from an expired request cannot disturb a retry that re-registered the key.
``DedupRecordingTaskStore`` records cacheable tasks as the SDK saves them.
"""

from __future__ import annotations

import asyncio
import time
from collections.abc import AsyncGenerator
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import TYPE_CHECKING, NamedTuple, Optional

import structlog
from a2a.server.context import ServerCallContext
from a2a.server.owner_resolver import resolve_user_scope
from a2a.server.tasks import TaskStore
from a2a.types import (
    Artifact,
    ListTasksRequest,
    ListTasksResponse,
    Message,
    SendMessageRequest,
    Task,
    TaskArtifactUpdateEvent,
    TaskState,
    TaskStatus,
    TaskStatusUpdateEvent,
)
from a2a.utils.task import apply_history_length
from google.protobuf.timestamp_pb2 import Timestamp
from pydantic import BaseModel, ConfigDict

if TYPE_CHECKING:
    from a2a.server.events import Event

from rasa.core.a2a_server.config import DEFAULT_A2A_TASK_TIMEOUT_SECONDS
from rasa.core.a2a_server.proto_convert import clone_proto, part_data

structlogger = structlog.get_logger()

# ``ServerCallContext.state`` key for the ``InFlightLease`` of this send.
IN_FLIGHT_LEASE_STATE_KEY = "rasa_a2a_in_flight_lease"

# Terminal / interactive-terminal states safe to replay for duplicate ``messageId``.
CACHEABLE_TASK_STATES = frozenset(
    {
        TaskState.TASK_STATE_COMPLETED,
        TaskState.TASK_STATE_INPUT_REQUIRED,
        TaskState.TASK_STATE_REJECTED,
        TaskState.TASK_STATE_FAILED,
        TaskState.TASK_STATE_CANCELED,
        TaskState.TASK_STATE_AUTH_REQUIRED,
    }
)

_INTERRUPTED_TASK_STATES = frozenset(
    {TaskState.TASK_STATE_INPUT_REQUIRED, TaskState.TASK_STATE_AUTH_REQUIRED}
)

_TURN_STARTED_STATES = frozenset(
    {TaskState.TASK_STATE_SUBMITTED, TaskState.TASK_STATE_WORKING}
)

DEFAULT_A2A_MESSAGE_CACHE_TTL_SECONDS = DEFAULT_A2A_TASK_TIMEOUT_SECONDS

# Time after the task timeout for the timeout handler to persist its terminal
# task. Interrupting a turn must stay within this bound.
IN_FLIGHT_GRACE_SECONDS = 30.0


class CacheKey(NamedTuple):
    """Idempotency key for one A2A ``message/send`` (or stream) request.

    - ``owner``: the authenticated caller, resolved the same way the SDK
      ``TaskStore`` scopes tasks (``ServerCallContext.user.user_name``). Two
      principals that reuse the same ``(context_id, message_id)`` pair must not
      see or block each other's entries.
    - ``context_id``: A2A conversation / session id (scopes dedup to one dialog).
    - ``message_id``: client ``Message.messageId``; retries with the same triple
      are treated as the same logical send.

    Used as the dict/set key for terminal-task replay and the in-flight registry
    (duplicate while still processing → HTTP 409).
    """

    owner: str
    context_id: str
    message_id: str


class TaskBindingKey(BaseModel):
    """Owner-scoped ``task_id`` used to look up the in-flight ``CacheKey``.

    Scoping by ``owner`` keeps one principal from attaching to, or reading the
    replay of, a task id that belongs to another principal.
    """

    model_config = ConfigDict(frozen=True)

    owner: str
    task_id: str


class InFlightLease(BaseModel):
    """One in-flight registration of a ``CacheKey``.

    A key can expire and be registered again by a retry while the expired
    request is still running. ``generation`` tells the two apart, so the
    expired request can no longer record a replay for, bind tasks to, or
    release the retry's registration.
    """

    model_config = ConfigDict(frozen=True)

    key: CacheKey
    generation: int


class _InFlightRegistration(BaseModel):
    model_config = ConfigDict(frozen=True)

    lease: InFlightLease
    expires_at: float
    turn_started: bool = False


def caller_scope(context: ServerCallContext | None) -> str:
    """Return the caller identity used to scope cache entries.

    Mirrors the owner the SDK ``InMemoryTaskStore`` uses by default so the
    idempotency cache and the task store agree on who may see a task.
    """
    if context is None:
        return resolve_user_scope(ServerCallContext())
    return resolve_user_scope(context)


@dataclass(frozen=True)
class A2AMessageCacheEntry:
    """One cached terminal outcome for an ``(owner, context_id, message_id)`` key."""

    recorded_at: float
    task: Task


class A2AMessageCache:
    """TTL cache of terminal tasks plus an in-flight registry per ``messageId``.

    An in-flight key stops blocking duplicates after ``in_flight_timeout_seconds``
    (default ``ttl_seconds``) plus ``in_flight_grace_seconds`` so a request that
    never reaches a cacheable save cannot wedge its key. ``0`` means the key
    never blocks a duplicate.

    The window restarts when the request's own turn starts. The executor arms
    its task timeout at the same point, so setup time and time spent queued
    behind an earlier turn on the same task do not eat into it. The grace
    period covers the terminal save the timeout handler writes after that
    timeout fires.
    """

    def __init__(
        self,
        *,
        ttl_seconds: int = DEFAULT_A2A_MESSAGE_CACHE_TTL_SECONDS,
        in_flight_timeout_seconds: int | None = None,
        in_flight_grace_seconds: float | None = None,
    ) -> None:
        self._ttl_seconds = ttl_seconds
        self._in_flight_timeout_seconds = (
            ttl_seconds
            if in_flight_timeout_seconds is None
            else in_flight_timeout_seconds
        )
        self._in_flight_grace_seconds = (
            IN_FLIGHT_GRACE_SECONDS
            if in_flight_grace_seconds is None
            else in_flight_grace_seconds
        )
        self._entries: dict[CacheKey, A2AMessageCacheEntry] = {}
        self._in_flight: dict[CacheKey, _InFlightRegistration] = {}
        self._task_bindings: dict[TaskBindingKey, InFlightLease] = {}
        self._next_generation = 0
        self._lock = asyncio.Lock()

    @property
    def ttl_seconds(self) -> int:
        return self._ttl_seconds

    async def get(self, key: CacheKey) -> Task | None:
        """Return a cached terminal ``Task`` copy, or ``None`` if missing or expired."""
        async with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                return None
            if self._is_expired(entry.recorded_at):
                del self._entries[key]
                return None
            return clone_proto(entry.task)

    async def try_begin_in_flight(self, key: CacheKey) -> InFlightLease | None:
        """Register in-flight processing. Returns ``None`` if already in flight."""
        async with self._lock:
            self._purge_expired_in_flight_locked()
            if key in self._in_flight:
                return None
            self._next_generation += 1
            lease = InFlightLease(key=key, generation=self._next_generation)
            self._in_flight[key] = _InFlightRegistration(
                lease=lease, expires_at=self._in_flight_deadline()
            )
            return lease

    async def end_in_flight(self, lease: InFlightLease) -> None:
        """Clear ``lease``'s registration (no-op once it expired or was replaced)."""
        async with self._lock:
            self._end_in_flight_locked(lease)

    async def finish_in_flight(
        self, lease: InFlightLease, replay: Task | None = None
    ) -> bool:
        """Record ``replay`` (if given) and clear ``lease``'s registration.

        Does nothing once ``lease`` expired or was replaced, so a request that
        outlived its in-flight window cannot overwrite the replay of, or
        release the 409 for, a retry that registered the same key after it.

        Returns:
            ``True`` when ``lease`` was current and has been finished.
        """
        async with self._lock:
            self._purge_expired_in_flight_locked()
            if not self._is_current_locked(lease):
                return False
            if replay is not None:
                self._record_locked(lease.key, replay)
            self._end_in_flight_locked(lease)
            return True

    async def mark_turn_started(self, lease: InFlightLease) -> None:
        """Note that ``lease``'s own turn has saved a ``submitted``/``working`` task.

        The first call restarts the in-flight window; later saves of the same
        turn do not extend it.
        """
        async with self._lock:
            self._purge_expired_in_flight_locked()
            registration = self._in_flight.get(lease.key)
            if (
                registration is None
                or registration.lease != lease
                or registration.turn_started
            ):
                return
            self._in_flight[lease.key] = registration.model_copy(
                update={"turn_started": True, "expires_at": self._in_flight_deadline()}
            )

    async def is_turn_started(self, lease: InFlightLease) -> bool:
        """Whether ``lease`` is current and its own turn has started."""
        async with self._lock:
            self._purge_expired_in_flight_locked()
            registration = self._in_flight.get(lease.key)
            return (
                registration is not None
                and registration.lease == lease
                and registration.turn_started
            )

    async def is_in_flight(self, key: CacheKey) -> bool:
        """Return whether ``key`` is registered and has not timed out."""
        async with self._lock:
            self._purge_expired_in_flight_locked()
            return key in self._in_flight

    async def in_flight_count(self) -> int:
        """Number of registered keys that have not timed out."""
        async with self._lock:
            self._purge_expired_in_flight_locked()
            return len(self._in_flight)

    async def bind_task(self, task_id: str, lease: InFlightLease) -> None:
        """Bind ``task_id`` to ``lease`` for saves that carry no stashed lease.

        Only a current lease is bound, so a binding never outlives the 409
        window. Bindings are scoped to the lease key's owner.
        """
        if not task_id:
            return
        async with self._lock:
            self._purge_expired_in_flight_locked()
            if self._is_current_locked(lease):
                self._task_bindings[
                    TaskBindingKey(owner=lease.key.owner, task_id=task_id)
                ] = lease

    async def lease_for_task(self, task_id: str, *, owner: str) -> InFlightLease | None:
        """Return the in-flight lease ``owner`` bound to ``task_id``, if any."""
        async with self._lock:
            self._purge_expired_in_flight_locked()
            return self._task_bindings.get(TaskBindingKey(owner=owner, task_id=task_id))

    async def record(self, key: CacheKey, task: Task) -> None:
        """Store a deep copy of ``task`` and evict expired entries."""
        async with self._lock:
            self._record_locked(key, task)

    async def close(self) -> None:
        """Clear all cached and in-flight state (server shutdown)."""
        async with self._lock:
            self._entries.clear()
            self._in_flight.clear()
            self._task_bindings.clear()

    def _in_flight_deadline(self) -> float:
        if self._in_flight_timeout_seconds <= 0:
            return time.monotonic()
        return (
            time.monotonic()
            + self._in_flight_timeout_seconds
            + self._in_flight_grace_seconds
        )

    def _record_locked(self, key: CacheKey, task: Task) -> None:
        self._purge_expired_locked()
        self._entries[key] = A2AMessageCacheEntry(
            recorded_at=time.time(),
            task=clone_proto(task),
        )

    def _is_current_locked(self, lease: InFlightLease) -> bool:
        registration = self._in_flight.get(lease.key)
        return registration is not None and registration.lease == lease

    def _end_in_flight_locked(self, lease: InFlightLease) -> None:
        if not self._is_current_locked(lease):
            return
        del self._in_flight[lease.key]
        self._drop_task_bindings_locked(lease)

    def _is_expired(self, recorded_at: float) -> bool:
        return (time.time() - recorded_at) > self._ttl_seconds

    def _purge_expired_locked(self) -> None:
        expired = [
            key
            for key, entry in self._entries.items()
            if self._is_expired(entry.recorded_at)
        ]
        for key in expired:
            del self._entries[key]

    def _purge_expired_in_flight_locked(self) -> None:
        now = time.monotonic()
        expired = [
            registration.lease
            for registration in self._in_flight.values()
            if now >= registration.expires_at
        ]
        for lease in expired:
            del self._in_flight[lease.key]
            self._drop_task_bindings_locked(lease)
            # A zero window is the configured "never block" setting, not a
            # request that ran too long.
            if self._in_flight_timeout_seconds > 0:
                structlogger.warning(
                    "a2a_server.a2a_message_cache.in_flight_expired",
                    event_info=(
                        "A request is still unfinished after the in-flight window, "
                        "so a retry with the same messageId will run the turn "
                        "again. If turns legitimately take this long, increase "
                        "`a2a_server.task_timeout_seconds` (or "
                        "`a2a_server.a2a_message_cache_ttl_seconds` when the task "
                        "timeout is disabled)."
                    ),
                    context_id=lease.key.context_id,
                    message_id=lease.key.message_id,
                    in_flight_timeout_seconds=self._in_flight_timeout_seconds,
                )

    def _drop_task_bindings_locked(self, lease: InFlightLease) -> None:
        stale = [ref for ref, bound in self._task_bindings.items() if bound == lease]
        for ref in stale:
            del self._task_bindings[ref]


def cache_key_from_message(
    *, owner: str, context_id: str | None, message_id: str | None
) -> Optional[CacheKey]:
    """Build a ``CacheKey`` when both A2A identifiers are non-empty."""
    if context_id and message_id:
        return CacheKey(owner=owner, context_id=context_id, message_id=message_id)
    return None


def cache_key_from_dispatch(
    message: Message,
    *,
    owner: str,
    context_id_fallback: str | None = None,
) -> Optional[CacheKey]:
    """Build a dedup key from ``message`` ids with optional context fallback."""
    context_id = message.context_id or context_id_fallback
    return cache_key_from_message(
        owner=owner,
        context_id=context_id,
        message_id=message.message_id,
    )


def should_cache_task(task: Task) -> bool:
    """Whether ``task`` is a terminal outcome worth caching for idempotent replay."""
    state = task.status.state
    if state not in CACHEABLE_TASK_STATES:
        return False
    if state != TaskState.TASK_STATE_FAILED:
        return True
    return _failed_task_is_structured_pattern_outcome(task)


def _failed_task_is_structured_pattern_outcome(task: Task) -> bool:
    """Distinguish pattern ``failed`` (cacheable) from executor fast-fail paths."""
    if not task.status.HasField("message"):
        return False
    return any(part_data(part) is not None for part in task.status.message.parts)


def _status_timestamp() -> Timestamp:
    timestamp = Timestamp()
    timestamp.FromDatetime(datetime.now(timezone.utc))
    return timestamp


def _replay_status(cached_task: Task) -> TaskStatus:
    status = TaskStatus(
        state=cached_task.status.state,
        timestamp=_status_timestamp(),
    )
    if cached_task.status.HasField("message"):
        status.message.CopyFrom(cached_task.status.message)
    return status


def _replay_artifact_event(
    artifact: Artifact,
    *,
    task_id: str,
    context_id: str,
) -> TaskArtifactUpdateEvent:
    event = TaskArtifactUpdateEvent(
        task_id=task_id,
        context_id=context_id,
        append=False,
        last_chunk=True,
    )
    event.artifact.CopyFrom(clone_proto(artifact))
    return event


def task_for_replay(
    cached_task: Task,
    *,
    task_id: str,
    context_id: str,
) -> Task:
    """Build a ``Task`` snapshot for the current request ids from a cache entry."""
    task = clone_proto(cached_task)
    task.id = task_id
    task.context_id = context_id
    return task


def replay_ids_for_message(
    cached_task: Task, params: SendMessageRequest
) -> tuple[str, str]:
    """Resolve ``task_id`` and ``context_id`` for replay from the inbound message."""
    message = params.message
    task_id = message.task_id or cached_task.id
    context_id = message.context_id or cached_task.context_id
    return task_id, context_id


def task_for_replay_from_params(cached_task: Task, params: SendMessageRequest) -> Task:
    """Return a cache replay ``Task`` shaped for the retry request.

    Ids come from ``params.message``. The cache holds the untrimmed stored task,
    so the retry's ``history_length`` is applied here, as the SDK does on the
    live path.
    """
    task_id, context_id = replay_ids_for_message(cached_task, params)
    task = task_for_replay(cached_task, task_id=task_id, context_id=context_id)
    return apply_history_length(task, params.configuration)


async def replay_cached_stream(
    cached_task: Task,
    params: SendMessageRequest,
) -> AsyncGenerator[Event, None]:
    """Yield stream events that reproduce a cached terminal outcome."""
    task_id, context_id = replay_ids_for_message(cached_task, params)
    yield task_for_replay_from_params(cached_task, params)
    for artifact in cached_task.artifacts:
        yield _replay_artifact_event(artifact, task_id=task_id, context_id=context_id)
    yield TaskStatusUpdateEvent(
        task_id=task_id,
        context_id=context_id,
        status=_replay_status(cached_task),
    )


def in_flight_lease_from_call_context(
    context: ServerCallContext | None,
) -> InFlightLease | None:
    """Read the stashed ``InFlightLease`` from ``ServerCallContext.state``."""
    if context is None:
        return None
    value = context.state.get(IN_FLIGHT_LEASE_STATE_KEY)
    if isinstance(value, InFlightLease):
        return value
    return None


class DedupRecordingTaskStore(TaskStore):
    """Task-store decorator that records replay and ends in-flight on cacheable saves.

    V2 treats a request as done when it persists a cacheable task. Recording the
    snapshot here (not from the handler return) covers blocking sends, streams,
    ``return_immediately``, and dropped SSE the same way.
    """

    def __init__(self, inner: TaskStore, message_cache: A2AMessageCache) -> None:
        self._inner = inner
        self._message_cache = message_cache

    async def save(self, task: Task, context: ServerCallContext) -> None:
        """Write ``task`` to the inner SDK store, then update the message cache."""
        await self._inner.save(task, context)
        await self._sync_message_cache(task, context)

    async def get(self, task_id: str, context: ServerCallContext) -> Task | None:
        """Delegate lookup to the inner store."""
        return await self._inner.get(task_id, context)

    async def list(
        self,
        params: ListTasksRequest,
        context: ServerCallContext,
    ) -> ListTasksResponse:
        """Delegate listing to the inner store."""
        return await self._inner.list(params, context)

    async def delete(self, task_id: str, context: ServerCallContext) -> None:
        """Delegate deletion to the inner store."""
        await self._inner.delete(task_id, context)

    async def _sync_message_cache(self, task: Task, context: ServerCallContext) -> None:
        """Record a replay snapshot and end the 409 lock when the save is cacheable.

        Inner ``save`` already wrote ``task`` to the SDK store. This does not
        delete that task. ``SUBMITTED`` / ``WORKING`` stay in flight.
        Unstructured ``FAILED`` still ends in-flight but is not recorded for
        replay (see ``should_cache_task``). A save whose lease expired or was
        replaced by a retry changes nothing.

        A follow-up's first save appends its user message to the task while the
        task still holds the previous turn's interrupted state. An interrupted
        save therefore only finishes a lease once that lease's own turn saved a
        ``submitted``/``working`` task. Terminal states need no such check: a
        terminal task accepts no follow-up.
        """
        lease = in_flight_lease_from_call_context(context)
        if lease is not None and task.id:
            await self._message_cache.bind_task(task.id, lease)
        elif task.id:
            lease = await self._message_cache.lease_for_task(
                task.id, owner=caller_scope(context)
            )
        if lease is None:
            return
        state = task.status.state
        if state in _TURN_STARTED_STATES:
            await self._message_cache.mark_turn_started(lease)
            return
        if state not in CACHEABLE_TASK_STATES:
            return
        if state in _INTERRUPTED_TASK_STATES and not (
            await self._message_cache.is_turn_started(lease)
        ):
            return
        replay = task if should_cache_task(task) else None
        finished = await self._message_cache.finish_in_flight(lease, replay)
        if not finished:
            structlogger.warning(
                "a2a_server.a2a_message_cache.late_save_ignored",
                event_info=(
                    "A request finished after its in-flight window expired. Its "
                    "result was saved to the task store but not recorded for "
                    "messageId replay."
                ),
                context_id=lease.key.context_id,
                message_id=lease.key.message_id,
                task_state=task.status.state,
            )
            return
        structlogger.debug(
            "a2a_server.a2a_message_cache.in_flight_finished",
            context_id=lease.key.context_id,
            message_id=lease.key.message_id,
            task_state=task.status.state,
            replay_recorded=replay is not None,
        )
